pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 originalVal, uint256 newVal, address actor) public {
        originalVal = bound(originalVal, 0, type(uint256).max / 2);
        newVal = bound(newVal, 0, type(uint256).max / 2);
        vm.assume(actor != address(0));

        // Set an initial MinSum while uninitialized (both versions succeed here).
        vm.prank(actor);
        c.SetMinSum(originalVal);
        assertEq(c.MinSum(), originalVal);

        // Initialize the contract: from now on SetMinSum must always revert.
        vm.prank(actor);
        c.Initialized();

        // A reverting SetMinSum must leave MinSum unchanged (universal rule).
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, newVal));

        assertTrue(!ok && c.MinSum() == originalVal);
    }
}

