pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, uint256 val) public {
        // seed: an initial legitimate MinSum set while uninitialized
        // val:  a later attempted update after initialization
        // Setup: while uninitialized, SetMinSum(seed) succeeds and sets MinSum = seed.
        c.SetMinSum(seed);

        // Freeze configuration: after Initialized(), every SetMinSum must be a no-op.
        c.Initialized();

        // Admissible domain: any value the attacker might try to force in.
        uint256 before = c.MinSum();
        bool ok;
        try c.SetMinSum(val) { ok = true; } catch { ok = false; }

        // General rule: an initialized contract never accepts a new MinSum —
        // the call reverts AND MinSum is unchanged, regardless of val.
        assertTrue(!ok && c.MinSum() == before);
    }
}

