pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialVal, uint256 newVal, address actor) public {
        // Wide admissible domain: any address, any values (newVal differing from initialVal is not required,
        // the fuzzer will find violating inputs on its own).
        vm.assume(actor != address(0));

        // While uninitialized, SetMinSum legitimately sets MinSum.
        vm.prank(actor);
        c.SetMinSum(initialVal);
        uint256 before = c.MinSum();

        // Freeze configuration: after Initialized(), SetMinSum must revert and leave state untouched.
        c.Initialized();

        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a reverting SetMinSum call must not change MinSum.
        assertTrue(!ok && c.MinSum() == before);
    }
}

