pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public {
        c = new C();
        caller = new Caller();
    }

    function testFuzz_property(address logAddr) public {
        // The caller is a contract (so Log(msg.sender) in the mutant does not revert);
        // the fuzzer supplies the log address. Exclude the degenerate case where the
        // log address equals the caller (there the two versions coincide).
        vm.assume(logAddr != address(caller));

        // A contract party calls SetLogFile with the fuzzed log address.
        caller.doSetLogFile(c, logAddr);

        // General rule: after SetLogFile(x) from any caller, the stored LogFile is x.
        assertTrue(address(c.LogFile()) == logAddr, "LogFile must equal the supplied log address");
    }
}

contract Caller {
    function doSetLogFile(C c, address log) external {
        c.SetLogFile(log);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function runTest(uint v, uint amt, uint am) public {
        require(v > 0);
        require(am > 0 && am < v);
        require(amt >= am);
        require(address(this).balance >= amt);
        c.SetMinSum(v);
        c.Initialized();
        c.Put{value: amt}(0);
        c.Collect(am);
        (bool ok, Holder memory h) = ...;
        assert(c.Acc(address(this)).balance == amt);
    }
    receive() external payable {}
    fallback() external payable {}
}
